/// <reference path="../pb_data/types.d.ts" />

/**
 * Временная проверка: каким видит клиента сервер.
 *
 * Ограничитель частоты считает запросы по адресу клиента, а за nginx все они
 * приходят с адреса самого nginx. Пока не известно, доходит ли доверенный
 * заголовок, включать лимиты нельзя: сервер посчитает всех пользователей
 * одним клиентом и начнёт отказывать всем сразу.
 *
 * Отдаёт только адрес самого спрашивающего — свой собственный адрес человек
 * и так знает, ничего чужого здесь не появляется.
 *
 * УДАЛИТЬ ПОСЛЕ ВКЛЮЧЕНИЯ ЛИМИТОВ. Этот файл живёт ровно до того момента,
 * когда станет понятно, что realIP отличается от remoteIP.
 */

routerAdd('GET', '/api/whoami', (e) => {
  return e.json(200, {
    // Кем сервер считает клиента с учётом доверенного заголовка.
    realIP: e.realIP(),
    // Кто соединился с сервером на самом деле: за nginx это сам nginx.
    remoteIP: e.remoteIP(),
  })
})
